export type Step3Case="partial_metadata"|"full_projection"|"per_unit"|"new_zero_activity"|"unknown"|"multiple_linked"|"specialized"|"volume_conflict"|"no_changes"|"current_edit"|"per_unit_unknown"|"per_unit_zero"|"product_pair";
type Scenario={body:OperatingPlanBody;evaluation:OperatingEvaluation;staff_evaluation:OperatingEvaluation;guidance:OperatingGuidance;evidence:OperatingEvidence;before_body?:OperatingPlanBody};
export function step3Scenario(name:Step3Case):Scenario{const base=encoded.partial_metadata as Record<string,unknown>,extra=encoded[name] as Record<string,unknown>;return structuredClone(Object.fromEntries([...new Set([...Object.keys(base),...Object.keys(extra)])].map(key=>[key,extra[key]&&typeof extra[key]==="object"&&!Array.isArray(extra[key])?{...(base[key] as object),...(extra[key] as object)}:extra[key]??base[key]]))) as unknown as Scenario;}
export function step3Initial(name?:Step3Case){return name?step3Scenario(name).body:operatingEditInitial();}
export function step3Snapshot(body:OperatingPlanBody,revision:number,name?:Step3Case):FinancialWorkspaceSnapshot{const base=operatingEditSnapshot(body,revision);return{...base,evidence:name?(step3Scenario(name).evidence.files??[]).map(row=>({...row,content_type:"application/pdf"})):base.evidence};}
/** Only metadata IDs are remapped for locally created rows/actions. All money values are immutable engine output. */
export function step3Reply(body:OperatingPlanBody,name?:Step3Case){
 if(!name)return operatingEditReply(body);
 const scenario=step3Scenario(name),ids=new Map<string,string>();
 for(const ref of scenario.body.expenses??[]){const row=body.expenses?.find(row=>row.id===ref.id)||body.expenses?.find(row=>row.source_group_key&&row.source_group_key===ref.source_group_key)||body.expenses?.find(row=>row.label===ref.label&&row.category===ref.category);if(row)ids.set(ref.id,row.id);}
 for(const ref of scenario.body.adjustments??[]){const row=body.adjustments?.find(row=>row.id===ref.id)||body.adjustments?.find(row=>row.kind===ref.kind&&(row.expense_row_id??"")===(ids.get(ref.expense_row_id??"")??ref.expense_row_id??""));if(row)ids.set(ref.id,row.id);}
 let json=JSON.stringify({evaluation:scenario.evaluation,guidance:scenario.guidance,evidence:scenario.evidence});for(const[oldId,newId]of ids)json=json.replaceAll(oldId,newId);return JSON.parse(json) as {evaluation:OperatingEvaluation;guidance:OperatingGuidance;evidence:OperatingEvidence;before_body?:OperatingPlanBody};
}
